(* [comment removed for export] *)
Lemma limbsB_w hb lb : 0 <= hb < 2 ^ 48 -> 0 <= lb < 2 ^ 64 ->
  let bLo15 := Z.land (Z.shiftl lb 15) 18446744073709551615 in
  let bHi15 := Z.lor (Z.shiftr lb 49) (Z.land (Z.shiftl hb 15) 18446744073709551615) in
  let B1 := Z.lor (Z.shiftr (Z.land (Z.shiftl hb 15) 18446744073709551615) 32) 2147483648 in
  let B2 := bHi15 mod 2 ^ 32 in let B3 := Z.shiftr bLo15 32 in let B4 := bLo15 mod 2 ^ 32 in
  (0 <= B1 < 2 ^ 32 /\ 0 <= B2 < 2 ^ 32 /\ 0 <= B3 < 2 ^ 32 /\ 0 <= B4 < 2 ^ 32)
  /\ B1 * 2 ^ 96 + B2 * 2 ^ 64 + B3 * 2 ^ 32 + B4 = ((hb + 2 ^ 48) * 2 ^ 64 + lb) * 2 ^ 15
  /\ (Z.shiftl bHi15 32) mod 2 ^ 64 = (B2 * 2 ^ 32) mod 2 ^ 64
  /\ (Z.shiftl bLo15 32) mod 2 ^ 64 = (B4 * 2 ^ 32) mod 2 ^ 64.
Proof.
