Hypothesis FR : rw_cells rsegs m (bv_unsigned sp + -80) [CB 8 junk; C8 os8; C8 os7; C8 os6; C8 os5; C8 os4; C8 os3; C8 os2; C8 os1; C8 os0].
Hypothesis ST : stk rsegs m lo (bv_unsigned sp + -80).
Hypothesis MI : mem_inv rsegs m.

Definition tail_post (rlo rhi : Z) : machine_state -> Prop := fun ms' =>
  exists t0' t1' t2' a2' a3' a4' a5' a6' a7',
    ms' = MS (mkR ra sp gp tp t0' t1' t2' os0 os1 (Z_to_bv 64 rlo) (Z_to_bv 64 rhi) a2' a3' a4' a5' a6' a7'
                  os2 os3 os4 os5 os6 os7 os8 s9 s10 s11 t3 t4 t5 t6) F (ret_pc ra) fc None m (seg_rom rsegs).

