Lemma mul_tailA (esum hh hl : Z) :
  (2 ^ 48 <= hh < 2 ^ 49)%Z -> (0 <= hl < 2 ^ 64)%Z -> (16383 <= esum <= 16383 + 32765)%Z ->
  evt rsegs (tail_post hl ((esum - 16382) * 2 ^ 48 + (hh - 2 ^ 48)))
    (MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp (Z_to_bv 64 esum) t1 (Z_to_bv 64 (-16383)) s0 s1
             (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 hh) (Z_to_bv 64 (-1)) (Z_to_bv 64 281474976710655) (Z_to_bv 64 hl)
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0x13bd20) fc None m (seg_rom rsegs)).
Proof.
