    (m : word -> option byte) (d : Z) : machine_state -> Prop :=
  fun ms' => exists t0' a2' a3' a4' a5' a6' a7',
      ms' = MS (mkR ra sp gp tp t0' t1 t2 s0 s1 (Z_to_bv 64 (lo64 (f128_of_d d))) (Z_to_bv 64 (hi64 (f128_of_d d))) a2' a3' a4' a5' a6' a7'
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (ret_pc ra) fc None m (seg_rom rsegs).



(* [comment removed for export] *)
Ltac model_goal_f128_of_d d :=
  unfold f128_of_d; unfold_sf; zb_fold_lits; rewrite (land_W_small d) by lia;
  repeat (progress zs_idioms); zb_fold_lits.

(* [comment removed for export] *)
Lemma extend_walk_nosub : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (d : Z),
  (0 <= d < 2 ^ 64)%Z -> ((d mod 2 ^ 63) / 2 ^ 52 <> 0 \/ d mod 2 ^ 63 = 0)%Z ->
  evt rsegs (extend_post ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (bvmap_set 10 (Z_to_bv 64 d) F) fc m d)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) (bvmap_set 10 (Z_to_bv 64 d) F) (Z_to_bv 64 0x136820) fc None m (seg_rom rsegs)).
