Lemma of_d_sub_regs d : 0 <= d < 2 ^ 64 -> 0 < d mod 2 ^ 63 < 2 ^ 52 ->
  hi64 (f128_of_d d) = (d / 2 ^ 63) * 2 ^ 63 + (15309 + Z.log2 (d mod 2 ^ 63)) * 2 ^ 48
                        + ((d mod 2 ^ 63) * 2 ^ (112 - Z.log2 (d mod 2 ^ 63)) / 2 ^ 64 - 2 ^ 48)
  /\ lo64 (f128_of_d d) = ((d mod 2 ^ 63) * 2 ^ (112 - Z.log2 (d mod 2 ^ 63))) mod 2 ^ 64.
