Definition limbs_ok (ws : list word) (lo hi : Z) : Prop :=
  forall i w, (lo <= i < hi)%Z -> nth_error ws (Z.to_nat i) = Some w -> (bv_unsigned w < 1000000000)%Z.

Lemma limbs_ok_upd ws lo hi i v : limbs_ok ws lo hi -> (0 <= v < 1000000000)%Z -> (0 <= i)%Z -> (0 <= lo)%Z ->
