Definition pass_post (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : word -> option byte) (ws : list word) (B ia iz : Z) : machine_state -> Prop :=
  fun ms' => exists (c' x' : Z) m' ws',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 (Z_to_bv 64 (B + 4 * (ia - 1))) (Z_to_bv 64 c') (Z_to_bv 64 x') (Z_to_bv 64 (x' mod 1000000000)) a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0x141ce8) fc None m' (seg_rom rsegs)
    /\ munch [(B + 4 * ia, B + 4 * iz)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ u32arr rsegs m' B ws' /\ length ws' = length ws /\ limbs_ok ws' ia iz
    /\ (forall i, (i < ia \/ iz <= i)%Z -> (0 <= i)%Z -> nth_error ws' (Z.to_nat i) = nth_error ws (Z.to_nat i))
    /\ (0 <= x' <= 999999999 * 2 ^ 29 + 1073741823)%Z /\ c' = (x' / 1000000000)%Z
    /\ (forall w, nth_error ws (Z.to_nat ia) = Some w -> bv_unsigned w <= x')%Z
    /\ nth_error ws' (Z.to_nat ia) = Some (Z_to_bv 64 (x' mod 1000000000)).

(* [comment removed for export] *)
Lemma pass_walk : forall (n : nat) (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (B ia sh c : Z) (ws : list word),
  mem_inv rsegs m -> u32arr rsegs m B ws -> (1 <= ia)%Z -> (ia + Z.of_nat n < Z.of_nat (length ws))%Z -> (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z ->
  limbs_ok ws ia (ia + Z.of_nat n + 1) -> (1 <= sh <= 29)%Z -> (0 <= c < 2 ^ 30)%Z ->
  a0 = Z_to_bv 64 MAGIC9 -> a1 = Z_to_bv 64 1000000000 -> a2 = Z_to_bv 64 (B + 4 * (ia + Z.of_nat n)) -> a3 = Z_to_bv 64 c ->
  s1 = Z_to_bv 64 (B + 4 * ia) -> s3 = Z_to_bv 64 sh ->
  evt rsegs (pass_post ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m ws B ia (ia + Z.of_nat n + 1))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0x141cb4) fc None m (seg_rom rsegs)).
