Notation rsegs := Asan_loaded_segments (only parsing).

Open Scope Z_scope.
Ltac sh9_cases sh H :=
  assert (sh = 1 \/ sh = 2 \/ sh = 3 \/ sh = 4 \/ sh = 5 \/ sh = 6 \/ sh = 7 \/ sh = 8 \/ sh = 9) as Hc by (clear - H; lia);
  clear H; repeat (destruct Hc as [Hc | Hc]; [subst sh; vm_compute; reflexivity|]); subst sh; vm_compute; reflexivity.
Lemma maskC_val sh : 1 <= sh <= 9 ->
  Z.lxor (Z.land (bv_swrap 32 (Z.shiftl 18446744073709551615 (sh mod 32))) 18446744073709551615) 18446744073709551615 = 2 ^ sh - 1.
Proof.
