Lemma lowz_step ws ws' ia iz q adv : lowz ws ia -> (0 <= ia < iz)%Z -> (0 <= q < 2 ^ 63)%Z ->
  (forall i, (i < ia \/ iz <= i)%Z -> (0 <= i)%Z -> nth_error ws' (Z.to_nat i) = nth_error ws (Z.to_nat i)) ->
  nth_error ws' (Z.to_nat ia) = Some (Z_to_bv 64 q) -> adv = (if (q =? 0)%Z then 1 else 0)%Z -> lowz ws' (ia + adv).
