Lemma j_val p e : 0 <= p < 2 ^ 20 -> -2 ^ 24 < e < 2 ^ 24 ->
  bv_swrap 32 (Z.land (bv_swrap 32 (p - Z.land (Z.b2z (0 <? p)) 1)) 18446744073709551615
               - Z.land (Z.land (0 + -1) 18446744073709551615) (Z.land e 18446744073709551615))
  = p - e - (if p =? 0 then 0 else 1).
Proof.
