Lemma fmtD2_walk : forall (ra sp gp tp t0 t1 t2 s0 a2 a3 a4 a5 a6 a7 s3 s7 s8 s9 s10 t3 t5 t6 : word)
   (F : bvmap 5 word) fc m (B ia iz ir p e j : Z) (jA jB : list byte),
  (0 <= p < 2 ^ 20)%Z -> (-1200 <= e <= 1200)%Z -> j = (p - e - (if (p =? 0)%Z then 0 else 1))%Z ->
  (0 <= ir <= 128)%Z -> (0 <= iz <= 128)%Z -> (0 <= B)%Z -> (B + 512 < 2 ^ 63)%Z ->
  mem_inv rsegs m ->
  rw_cells rsegs m (bv_unsigned s0 + -544) [C8 (Z_to_bv 64 0); CB 40 jA; C8 (Z_to_bv 64 1); C8 (Z_to_bv 64 103); CB 8 jB] -> (bv_unsigned s0 < 2 ^ 63)%Z -> (1024 <= bv_unsigned s0)%Z ->
